  results.inputValueAfterWhitespace = await input.inputValue();
  // leading/trailing spaces
  await input.fill('   walk the dog   ');
  await input.press('Enter');
  results.titles = await page.getByTestId('todo-title').allInnerTexts();
  results.storage = await page.evaluate(() => localStorage.getItem('react-todos'));
  // duplicate
  await input.fill('buy milk');
  await input.press('Enter');
  results.titlesAfterDup = await page.getByTestId('todo-title').allInnerTexts();
  results.count = await page.getByTestId('todo-count').innerText();
