async (page) => {
  const r = {};
  await page.evaluate(() => localStorage.clear());
  await page.goto('https://demo.playwright.dev/todomvc/');
  const input = page.getByPlaceholder('What needs to be done?');
  for (const t of ['one', 'two', 'three']) { await input.fill(t); await input.press('Enter'); }
  const item = page.getByTestId('todo-item').filter({ hasText: 'two' });
  await item.dblclick();
  r.liClassDuringEdit = await item.getAttribute('class');
  const edit = item.getByRole('textbox', { name: 'Edit' });
  r.editVisible = await edit.isVisible();
  r.editValue = await edit.inputValue();
  r.editFocused = await edit.evaluate(el => el === document.activeElement);
  r.selectionStart = await edit.evaluate(el => [el.selectionStart, el.selectionEnd]);
  // escape cancels
  await edit.fill('two edited');
  await edit.press('Escape');
  r.afterEscape = await page.getByTestId('todo-title').allInnerTexts();
  r.editStillVisible = await item.getByRole('textbox', { name: 'Edit' }).isVisible().catch(() => 'gone');
  // enter saves + trims
  await item.dblclick();
  await item.getByRole('textbox', { name: 'Edit' }).fill('   two renamed   ');
  await item.getByRole('textbox', { name: 'Edit' }).press('Enter');
  r.afterEnter = await page.getByTestId('todo-title').allInnerTexts();
  r.storage = await page.evaluate(() => localStorage.getItem('react-todos'));
  return r;
}

