async (page) => {
  const r = {};
  await page.evaluate(() => localStorage.clear());
  await page.goto('https://demo.playwright.dev/todomvc/');
  const input = page.getByPlaceholder('What needs to be done?');
  for (const t of ['alpha', 'beta', 'gamma']) { await input.fill(t); await input.press('Enter'); }
  const del = page.getByTestId('todo-item').filter({ hasText: 'beta' }).getByRole('button', { name: 'Delete' });
  r.deleteVisibleNoHover = await del.isVisible();
  r.deleteOpacity = await del.evaluate(el => getComputedStyle(el).opacity);
  await del.click();
  r.afterDelete = await page.getByTestId('todo-title').allInnerTexts();

  // filters
  await page.getByTestId('todo-item').filter({ hasText: 'alpha' }).getByRole('checkbox', { name: 'Toggle Todo' }).check();
  await page.getByRole('link', { name: 'Active' }).click();
  r.activeUrl = page.url();
  r.activeTitles = await page.getByTestId('todo-title').allInnerTexts();
  r.selectedActive = await page.locator('.filters a.selected').innerText();
  await page.getByRole('link', { name: 'Completed' }).click();
  r.completedUrl = page.url();
  r.completedTitles = await page.getByTestId('todo-title').allInnerTexts();
  r.countOnCompleted = await page.getByTestId('todo-count').innerText();
  // toggle while on completed view -> item should vanish
  await page.getByTestId('todo-item').filter({ hasText: 'alpha' }).getByRole('checkbox', { name: 'Toggle Todo' }).uncheck();
  r.completedTitlesAfterUncheck = await page.getByTestId('todo-title').allInnerTexts();
  r.mainVisibleOnEmptyFilter = await page.locator('.main').isVisible().catch(e => 'err');
  r.footerVisible = await page.locator('.footer').isVisible();
  r.toggleAllVisible = await page.locator('#toggle-all').count();
  // back navigation
  await page.goBack();
  r.afterBackUrl = page.url();
  r.afterBackTitles = await page.getByTestId('todo-title').allInnerTexts();
  return r;
}

async (page) => {
  const r = {};
  const li = page.getByTestId('todo-item').filter({ hasText: 'beta' });
  r.count = await li.count();
  const del = li.getByRole('button', { name: 'Delete' });
  r.delCount = await del.count();
  r.delVisible = await del.isVisible();
  r.styles = await li.locator('.destroy').evaluate(el => { const s = getComputedStyle(el); return { display: s.display, opacity: s.opacity, visibility: s.visibility }; }, { timeout: 3000 }).catch(e => String(e).slice(0,150));
  r.stylesHandle = await page.evaluate(() => { const el = document.querySelectorAll('.destroy')[1]; const s = getComputedStyle(el); return { display: s.display, opacity: s.opacity, visibility: s.visibility, w: s.width }; });
  // try hover then click
  await li.hover();
  r.delVisibleAfterHover = await del.isVisible();
  await del.click({ timeout: 5000 }).then(() => r.clicked = true).catch(e => r.clicked = String(e).slice(0,200));
  r.titles = await page.getByTestId('todo-title').allInnerTexts();
  return r;
}

